ProtocolType GreLayer::getGREVersion(uint8_t* greData, size_t greDataLen)
{
        if (greDataLen < sizeof(gre_basic_header))
                return UnknownProtocol;

        uint8_t version = *(greData+1);
        version &= 0x07;
        if (version == 0)
                return GREv0;
        else if (version == 1)
                return GREv1;
        else
                return UnknownProtocol;
}

